def chain_chain(chain):
    chain_dict = {}
    for token in chain:
        if token not in chain_dict:
            chain_dict[token] = []
        chain_dict[token].append(token)

    chain_dict[chain[-1]].append(chain[0])

    result = []
    current = chain[-1]
    while current in chain_dict:
        result.append(current)
        current = chain_dict[current][0]

    return ','.join(result)
